//! The stars, embedded.
//!
//! The **Yale Bright Star Catalogue**, 5th revised edition, cut at visual
//! magnitude 5.0 — 1,630 stars, which is roughly what a person sees under good
//! conditions. Parsed from `bsc5.dat` as published by the Harvard–Smithsonian
//! Center for Astrophysics Telescope Data Center:
//!
//! <http://tdc-www.harvard.edu/catalogs/bsc5.html>
//!
//! Positions are J2000, converted from the catalogue's sexagesimal right
//! ascension and declination. Precession moves them about a fiftieth of a degree
//! a year, so this is good for a human lifetime at the scale it is drawn.
//!
//! ## This file replaced ninety-two stars entered by hand
//!
//! The first version shipped a curated list of the brightest named stars,
//! because fetching the real catalogue needed a network and writing 1,630
//! entries from memory would have meant inventing most of them — plausible,
//! confident and wrong, which is the one failure mode a star catalogue cannot
//! survive: nobody checks a coordinate they cannot see is off. That reasoning
//! was sound and the conclusion was still worth
//! revisiting: the catalogue is a single 590 KB request with no authentication,
//! and once it is a *file* rather than a memory there is nothing to invent.
//!
//! It also mattered more than it looked. Ninety-two visible stars is about a
//! magnitude-3.3 sky — a badly light-polluted urban one — against the ~800 above
//! the horizon here. Being an order of magnitude short is enough on its own to
//! read as scattered dots rather than as a sky, independently of how each one is
//! drawn.
//!
//! Nine stars in the cut carry no B−V in the catalogue. They are given 0.44,
//! the neutral-white point (see `celestial::star_colour`), rather than dropped.

/// One catalogued star.
#[derive(Debug, Clone, Copy)]
pub struct Star {
    /// Harvard Revised number — the catalogue's own identifier, and a stable
    /// way to name a star that has no common name.
    pub hr: u16,
    /// The Bayer or Flamsteed designation, as the catalogue gives it.
    pub name: &'static str,
    /// J2000 right ascension, degrees.
    pub right_ascension_deg: f64,
    /// J2000 declination, degrees.
    pub declination_deg: f64,
    /// Apparent visual magnitude — smaller is brighter, and it is logarithmic.
    pub magnitude: f32,
    /// B−V colour index. Negative is blue-white, positive is orange-red.
    ///
    /// This is what stops a star field reading as scattered white dots: a
    /// faintly amber Betelgeuse next to a blue Rigel is most of what makes it
    /// look like the sky.
    pub colour_index: f32,
}

/// Every star brighter than magnitude 5.0, brightest first.
///
/// `approx_constant` is allowed because two stars in the cut have a visual
/// magnitude of exactly 3.14, and clippy reads that as a botched π. They are
/// measurements, not constants — HR 2653 and HR 4630 really are that bright.
#[allow(clippy::approx_constant)]
