#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    /// A number the catalogue's own documentation and an independent count both
    /// give. KStars records the empirical law `n = 10^(0.45*maglim + 0.95)`,
    /// which predicts 1,585 at magnitude 5.0 — within 3% of what is here.
    #[test]
    fn the_cut_holds_the_number_of_stars_a_magnitude_five_sky_has() {
        assert_eq!(STARS.len(), 1630);
    }

    /// Coordinates outside their ranges would project somewhere plausible and
    /// silently wrong, so the whole table is checked rather than spot-checked.
    #[test]
    fn every_catalogued_star_has_coordinates_that_exist() {
        for star in STARS {
            assert!(
                (0.0..360.0).contains(&star.right_ascension_deg),
                "{}: right ascension {}",
                star.name,
                star.right_ascension_deg
            );
            assert!(
                (-90.0..=90.0).contains(&star.declination_deg),
                "{}: declination {}",
                star.name,
                star.declination_deg
            );
            assert!(
                star.magnitude <= 5.0,
                "{} at magnitude {} is past the cut",
                star.name,
                star.magnitude
            );
            assert!(
                (-1.0..3.5).contains(&star.colour_index),
                "{}: colour index {}",
                star.name,
                star.colour_index
            );
        }
    }

    /// A duplicated entry draws one star twice, which at low alpha reads as one
    /// brighter star in the wrong place on the magnitude scale.
    #[test]
    fn no_star_is_listed_twice() {
        let mut seen = HashSet::new();
        for star in STARS {
            assert!(seen.insert(star.hr), "HR {} appears twice", star.hr);
        }
    }

    /// Spot-checks against an almanac, by Harvard Revised number so there is no
    /// ambiguity about which star is meant. Chosen to span the sky: the
    /// brightest, one at the pole, one deep in the south. A systematic error —
    /// hours taken for degrees, say — would move all three.
    #[test]
    fn the_famous_stars_are_where_the_almanac_puts_them() {
        let find = |hr: u16| {
            *STARS
                .iter()
                .find(|s| s.hr == hr)
                .unwrap_or_else(|| panic!("HR {hr} is missing"))
        };

        // Sirius, HR 2491: 06h 45m 09s, −16° 43′.
        let sirius = find(2491);
        assert!((sirius.right_ascension_deg - 101.287).abs() < 0.02);
        assert!((sirius.declination_deg + 16.716).abs() < 0.02);
        assert!(sirius.magnitude < -1.0, "Sirius is the brightest star");

        // Polaris, HR 424, sits within a degree of the celestial pole — which
        // is the whole reason anyone cares about it.
        assert!(find(424).declination_deg > 89.0);

        // Acrux, HR 4730, never rises from San Francisco.
        assert!(find(4730).declination_deg < -60.0);
    }

    /// Colour is carried so the field is not monochrome, and the two stars
    /// everyone can name as red and blue must actually differ. If the index
    /// were dropped or zeroed this is what would notice.
    #[test]
    fn betelgeuse_is_redder_than_rigel() {
        let find = |hr: u16| STARS.iter().find(|s| s.hr == hr).unwrap();
        assert!(find(2061).colour_index > 1.5, "Betelgeuse");
        assert!(find(1713).colour_index < 0.0, "Rigel");
    }

    /// The catalogue spans real stellar colours end to end. A parse that lost
    /// the B−V column would leave everything at the neutral default and this is
    /// what would catch it.
    #[test]
    fn the_field_spans_blue_to_red() {
        let bluest = STARS
            .iter()
            .map(|s| s.colour_index)
            .fold(f32::MAX, f32::min);
        let reddest = STARS
            .iter()
            .map(|s| s.colour_index)
            .fold(f32::MIN, f32::max);
        assert!(bluest < -0.2, "bluest star is only {bluest}");
        assert!(reddest > 1.8, "reddest star is only {reddest}");
    }
}
